#!/usr/bin/env bash
set -e
# Maestro de clientes/socios (Codigo, Nombre, Direccion completa), a partir
# del problema real que reporto Raul: el Excel de Pedidos que exporta el ERP
# trae el codigo de cliente en cada linea pero NO la direccion de entrega
# (en el ERP la direccion vive en la ficha del socio/cliente, no en la linea
# de pedido) -- por eso la carga de pedidos daba error de direccion en todos
# los pedidos.
#
# Solucion: un segundo import, independiente del de Pedidos, con solo 3
# columnas (Codigo, Nombre, Direccion completa). Se detecta automaticamente
# el codigo postal (5 digitos) dentro del texto de la direccion, y cuando es
# posible tambien la poblacion y la provincia. Una vez cargado:
#   - Nuevo boton "Importar direcciones" en Maestros > Clientes.
#   - La importacion de Pedidos usa esa direccion por defecto para cualquier
#     pedido de ese cliente que no traiga su propia direccion de entrega.
#   - Si el pedido SI trae su propia direccion, esa tiene prioridad.
#   - Ahora solo son obligatorios direccion + codigo postal (de uno de los
#     dos sitios); poblacion y provincia son opcionales (antes los 4 eran
#     obligatorios y bloqueaban toda la carga).
#
# Cambio de esquema (aditivo, solo columnas nuevas opcionales en Customer):
# defaultAddress, defaultCity, defaultProvince, defaultPostalCode. Requiere
# "npx prisma db push" (se hace solo, mas abajo). Ejecutar desde la raiz del
# repo.

echo "Escribiendo backend/prisma/schema.prisma..."
mkdir -p "$(dirname backend/prisma/schema.prisma)"
base64 -d > backend/prisma/schema.prisma <<'B64EOF'
