echo "Regenerando cliente Prisma y aplicando el cambio de schema..."
(cd backend && npx prisma generate && npx prisma db push)
echo "Compilando backend..."
(cd backend && npm run build)
echo "Compilando frontend (Backoffice)..."
(cd frontend && npm run build)
echo "Listo. Maestros > Clientes tiene ahora el boton 'Importar direcciones'."
